!function(e){function n(n){for(var t,a,o=n[0],m=n[1],s=n[2],d=0,_=[];d<o.length;d++)a=o[d],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&_.push(i[a][0]),i[a]=0;for(t in m)Object.prototype.hasOwnProperty.call(m,t)&&(e[t]=m[t]);for(c&&c(n);_.length;)_.shift()();return p.push.apply(p,s||[]),r()}function r(){for(var e,n=0;n<p.length;n++){for(var r,a=p[n],o=!0,m=1;m<a.length;m++)r=a[m],0!==i[r]&&(o=!1);o&&(p.splice(n--,1),e=t(t.s=a[0]))}return e}function t(n){if(a[n])return a[n].exports;var r=a[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},i={50:0},p=[];t.m=e,t.c=a,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var a in e)t.d(r,a,function(n){return e[n]}.bind(null,a));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=n,o=o.slice();for(var s=0;s<o.length;s++)n(o[s]);var c=m;p.push([218,0]),r()}({218:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(219),r(1))},219:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"sWG40与sWG41型简易火箭弹发射架","description":"<p>sWG40与sWG41型火箭弹发射架是二战德军最早开发的一种重型火箭弹简易发射装置，sWG40型为木质结构，是一个单体发射箱；而sWG41型为钢质结构，有单体发射箱也有可调节发射角度的四联装发射箱。这两种发射架可以发射直径280mm的高爆火箭弹和直径320mm的火箭燃烧弹，是一种重型火箭发射器。这两种发射架由德国多个军工厂生产，产量很大，生产一直到二战结束为止。</p><p>sWG40与sWG41型火箭弹发射架制造简单，转移方便，可先调好发射角度布置在预设阵地上，也可以用机动车运输至战场进行临时布置，但由于发射架射出的火箭弹有效射程只有2千米左右，所以只能布置在一线战场的重点作战区域作近程火力支援。且由于射击时无法瞄准，只能根据经验调整射击角度，所以只能作大面积的火力覆盖。</p><p>这种简易火箭弹发射装置还被装在Sdkfz 251型半履带装甲车两侧，成为火箭发射车，由于发射时声音与德军斯图卡俯冲轰炸时的声音十分相似，故德军将这种半履带火箭发射车又称为“陆地斯图卡”。（详见“<a href=\\"de_army_avhtv2511&Kfz4.html\\">251/1、Sd.Kfz 4/1型半履带装甲火箭炮车</a>”）</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonsWG_11.jpg","description":"<p>sWG40/41型火箭弹发射架所配备的280mm高爆弹与320mm燃烧弹技术数据：</p><h6>（图1）280mm高爆弹</h6><p>弹长：1190毫米；炸药直径：280毫米；发射火药直径：140毫米；</p><p>弹重：83公斤；战斗部炸药（40/60）36公斤；发射火药：6.6公斤；</p><p>喷射推进管长：410毫米；喷射推进管直径：120毫米；喷射孔径：23毫米；</p><p>倾斜喷射环孔直径：10毫米；</p><p>火箭弹射程：750～1925米。</p><h6>（图2）320mm燃烧弹</h6><p>弹长：1290毫米；炸药直径：830毫米；发射火药直径：460毫米；</p><p>弹重：79.2公斤；</p><p>火箭弹射程：770～2200米。</p><p>注：此型火箭弹发射架内框具有6条轨道，通过插入不同尺寸的导轨垫可以方便地改变发射口径，因此它可以发射280mm口径的高爆弹，也可以发射320mm口径的燃烧弹。</p>","caption":""}],"part2title":"战场上的sWG40与sWG41型简易火箭弹发射架","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonsWG_21.jpg","description":"东线苏联战场，德军一处预设的sWG40与sWG41型火箭弹发射架阵地。图中右边4具是sWG40型发射架，左边另有5具单体sWG41型发射架，它们以相同的发射角度成一排架设在雪地中，炮兵们作最后的发射准备。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_22.jpg","description":"东线苏联战场，德军正在设置一处sWG41型火箭弹发射架阵地；发射架架设在土坑中，一是为了方便排导发射时产生的火焰，二是为了隐藏火箭架发射阵地。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_23.jpg","description":"1943年，东线苏联战场库尔斯克前线，一个280/320mm Nb.Wf41火箭炮组士兵正从弹药车上将火箭弹卸下，准备进行装填。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_24.jpg","description":"接上图，发射架内火箭弹已装填完毕，炮兵正作最后检查，该发射架安装在轮式小车架上，发射前可根据射击目标调整发射角度。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_25.jpg","description":"1944年波兰，为了镇压华沙起义，德军正在华沙街道上安装sWG40型火箭弹发射架，他们将多个40型单体发射架放置在金属的底架上，成为一个由多个火箭弹发射架组成的火箭弹发射装置；图中使用的火箭弹是320mm口径燃烧弹。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_26.jpg","description":"1944年波兰，德军用sWG40型和sWG41型火箭弹发射架向华沙起义的市民发射高爆弹与燃烧弹，地面上还可以见到很多使用过的木制发射架。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_27.jpg","description":"一名德军炮兵正在抱起一枚280mm高爆弹，准备将其装填到旁边的sWG41型火箭弹发射架上，为了搬运安全，这些火箭弹都未装击发引信。其实，一个人去搬运这种每个重达80多公斤的火箭弹是十分辛苦的，这位士兵的笑容更可能是为了摆拍。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_28.jpg","description":"德军炮兵正在进行sWG41型火箭弹发射架的火箭弹装填，发射架旁边地面上还有多个未装击发引信的火箭弹。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_29.jpg","description":"二战中后期，德军又开发了一种可以用sWG40与sWG41型火箭弹发射架发射的300mm口径高爆弹；到了1944年，德军还生产了一种专用的Nb.Wf42型（56型）300mm火箭发射架。图为已装填好火箭弹的300mm Nb.Wf42型火箭发射架。Nb.Wf42型火箭发射架主要装备给摩托化300mm重型火箭炮连，每连弹药基数为120枚，每台发射架有可供5次半发射的33枚火箭弹。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_30.jpg","description":"正在发射的德军一门300mm Nb.Wf42型火箭发射架。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_31.jpg","description":"绘图：一辆挂载了sWG40型简易火箭弹发射架被德军称为“陆地斯图卡”的251/1B型半履带装甲火箭炮车。","caption":""},{"image":"imgs/de/army/de_army_cannonsWG_32.jpg","description":"绘图：德军251/1B型半履带装甲火箭炮车所挂载的sWG40型简易火箭弹发射架与火箭弹。","caption":""}]}')}});